-- chiang-mai: checked place by place on 2026-10-25 (still open, own websites, prices with sources).

UPDATE "Place" p SET "website" = 'https://www.rayaheritage.com/en/' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'chiang-mai' AND p.slug = 'raya-heritage';
UPDATE "Place" p SET "website" = 'https://thewingboutique.com/en/', "area" = 'Old City' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'chiang-mai' AND p.slug = 'the-wing-boutique';
UPDATE "Place" p SET "tip" = 'Open November to May only; the trail closes every June to October for the rains.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'chiang-mai' AND p.slug = 'kew-mae-pan-trail';
UPDATE "Place" p SET "area" = 'Hai Ya' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'chiang-mai' AND p.slug = 'khao-soi-lung-prakit';
UPDATE "Place" p SET "area" = 'Suthep Road' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'chiang-mai' AND p.slug = 'loong-thai';
